--- <campaign>/ios-provider-before-projection.swift	2026-10-18 18:40:38
+++ <campaign>/apple-sdk/XrayClient/Tunnel/PacketTunnelProvider.swift	2026-10-18 18:40:38
@@ -1,4 +1,5 @@
 import XrayAppleTunnel
+import XrayMobileAdapter
 #if DEBUG
 import Darwin
 import Foundation
@@ -7,6 +8,11 @@
 @available(iOSApplicationExtension 15.0, tvOSApplicationExtension 17.0, *)
 final class PacketTunnelProvider: XrayPacketTunnelProvider {
 #if DEBUG
+    private let projection = ProjectionCounters()
+    override func tunAdmissionOptions() throws -> XrayTunAdmissionOptions? {
+        let counters = projection
+        return try XrayTunAdmissionOptions { flow in counters.record(flow); return true }
+    }
     // Reference-app instrumentation only. CPU belongs to this extension,
     // including all live and terminated threads; no SDK or FFI ABI change.
     override func handleAppMessage(_ data: Data, completionHandler: ((Data?) -> Void)?) {
@@ -18,10 +24,29 @@
         guard getrusage(RUSAGE_SELF, &usage) == 0 else { completionHandler?(nil); return }
         let user = Double(usage.ru_utime.tv_sec) + Double(usage.ru_utime.tv_usec) / 1_000_000
         let system = Double(usage.ru_stime.tv_sec) + Double(usage.ru_stime.tv_usec) / 1_000_000
-        completionHandler?(try? JSONSerialization.data(withJSONObject: [
-            "userSeconds": user, "systemSeconds": system,
-            "uptime": ProcessInfo.processInfo.systemUptime, "pid": Double(getpid())
-        ]))
+        var values = projection.snapshot()
+        values["userSeconds"] = user; values["systemSeconds"] = system
+        values["uptime"] = ProcessInfo.processInfo.systemUptime; values["pid"] = Double(getpid())
+        completionHandler?(try? JSONSerialization.data(withJSONObject: values))
     }
 #endif
 }
+
+#if DEBUG
+private final class ProjectionCounters: @unchecked Sendable {
+    private let lock = NSLock()
+    private var tcp = 0, udp = 0, invalid = 0
+    func record(_ flow: XrayTunFlow) {
+        lock.lock(); defer { lock.unlock() }
+        if flow.protocolNumber == 6 { tcp += 1 }
+        if flow.protocolNumber == 17 { udp += 1 }
+        let length = flow.addressFamily == 4 ? 4 : (flow.addressFamily == 6 ? 16 : 0)
+        if length == 0 || flow.sourceAddress.count != length || flow.destinationAddress.count != length
+            || flow.sourcePort == 0 || flow.destinationPort == 0 { invalid += 1 }
+    }
+    func snapshot() -> [String: Double] {
+        lock.lock(); defer { lock.unlock() }
+        return ["admissionTCP": Double(tcp), "admissionUDP": Double(udp), "invalidTuples": Double(invalid)]
+    }
+}
+#endif
